SELECT sym, count() AS days_traded, sum(n_quotes) AS total_quotes, min(bp_min) AS lowest_bid, max(bp_max) AS highest_bid, sum(spread_sum) / sum(n_quotes) AS avg_spread FROM quotes_daily WHERE sym IN ('AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'META', 'NVDA', 'NFLX') GROUP BY sym ORDER BY total_quotes DESC LIMIT 1000000 SETTINGS max_threads=4,enable_parallel_replicas=0,max_parallel_replicas=1,use_query_cache=0,log_queries=1,log_query_settings=1,log_queries_probability=1,log_queries_min_query_duration_ms=0,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,max_result_rows=1000000,result_overflow_mode='throw',log_comment='reader-scaling-20261011T093715Z-pilot' FORMAT Null
